sp_widget.client_script:
api.controller = function($scope) { 
    $scope.goToSubmitFeedback = function() { 
        var recordProducerSysId = '-1'; 
        var url = '/sp?id=sc_cat_item&sys_id=' + recordProducerSysId; 
        window.location.href = url; 
    }; 
};

sp_widget.css:
.custom-action-card-feedback {
    background: #f2f8fc; /* very light sky blue background */
    border-radius: 12px;
    padding: 24px 20px;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.04);
    border: 1px solid #d0e3f0; /* soft blue-gray border */
    text-align: center;
}

.custom-action-card-feedback h4 {
    margin-bottom: 16px;
    font-weight: 600;
    color: #3a5668; /* cool gray-blue heading */
    font-size: 18px;
}

.action-btn-feedback {
    background: #cbe4f6; /* soft sky blue button */
    color: #2c4553; /* deeper cool gray for text */
    padding: 10px 18px;
    font-size: 14px;
    border: none;
    border-radius: 6px;
    width: 100%;
    cursor: pointer;
    transition: background 0.2s ease;
}

.action-btn-feedback:hover {
    background: #b3d6ee; /* slightly darker on hover */
}
